export const STRINGS: Record<Lang, typeof AR> = { ar: AR, en: EN };

export function pick<T extends { ar: string; en: string }>(obj: T, lang: Lang): string { return lang === 'ar' ? obj.ar : obj.en || obj.ar; }

/** الوقت النسبي: «منذ ٣ أيام» / "3 days ago" */
export function relTime(ms: number, lang: Lang, now = Date.now()): string {
  const s = STRINGS[lang].common; const d = Math.max(0, now - ms);
  const mins = Math.round(d / 60000), hrs = Math.round(d / 3600000), days = Math.round(d / 86400000);
  if (mins < 2) return s.now;
  if (lang === 'ar') {
    if (mins < 60) return `منذ ${mins} ${mins <= 10 ? 'دقائق' : 'دقيقة'}`;
    if (hrs < 24) return hrs === 1 ? 'منذ ساعة' : hrs === 2 ? 'منذ ساعتين' : `منذ ${hrs} ${hrs <= 10 ? 'ساعات' : 'ساعة'}`;
    return days === 1 ? 'منذ يوم' : days === 2 ? 'منذ يومين' : `منذ ${days} ${days <= 10 ? 'أيام' : 'يوماً'}`;
  }
  if (mins < 60) return `${mins} min ago`;
  if (hrs < 24) return `${hrs} h ago`;
  return `${days} d ago`;
}

/** مدة: «٣ أيام» / "3 days" */
export function durText(ms: number, lang: Lang): string {
  const hrs = Math.round(ms / 3600000), days = Math.round(ms / 86400000);
  if (lang === 'ar') { if (hrs < 24) return hrs <= 1 ? 'ساعة' : hrs === 2 ? 'ساعتان' : `${hrs} ${hrs <= 10 ? 'ساعات' : 'ساعة'}`; return days === 1 ? 'يوم' : days === 2 ? 'يومان' : `${days} ${days <= 10 ? 'أيام' : 'يوماً'}`; }
  if (hrs < 24) return `${Math.max(1, hrs)} h`; return `${days} d`;
}

export function fmtDate(ms: number, lang: Lang, opts: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'long', year: 'numeric' }): string {
  return new Intl.DateTimeFormat(lang === 'ar' ? 'ar-SA-u-nu-latn-ca-gregory' : 'en-GB', opts).format(new Date(ms));
}
export function fmtNum(n: number, lang: Lang, frac = 0): string {
  return new Intl.NumberFormat(lang === 'ar' ? 'ar-SA-u-nu-latn' : 'en-GB', { minimumFractionDigits: frac, maximumFractionDigits: frac }).format(n);
}
export function daysUntil(ms: number, now = Date.now()): number { return Math.ceil((ms - now) / 86400000); }
/** عدد الأيام بصيغة عربية سليمة: يوم واحد، يومان، 3 أيام، 11 يوماً؛ ونصف يوم */
export function daysText(n: number, lang: Lang): string {
  if (lang !== 'ar') return n === 0.5 ? 'half a day' : `${n} day${n === 1 ? '' : 's'}`;
  if (n === 0.5) return 'نصف يوم'; if (n === 1) return 'يوم واحد'; if (n === 2) return 'يومان'; if (n >= 3 && n <= 10) return `${n} أيام`; return `${n} يوماً`;
}
export function workingDaysText(n: number, lang: Lang): string {
  if (lang !== 'ar') return n === 0.5 ? 'half a working day' : `${n} working day${n === 1 ? '' : 's'}`;
  if (n === 0.5) return 'نصف يوم عمل'; if (n === 0) return 'بلا أيام عمل'; if (n === 1) return 'يوم عمل واحد'; if (n === 2) return 'يوما عمل'; if (n >= 3 && n <= 10) return `${n} أيام عمل`; return `${n} يوم عمل`;
}
/** عدد التغييرات بصيغة عربية سليمة */
export const changesText = (n: number, lang: Lang) => (lang === 'ar' ? (n === 1 ? 'تغيير واحد' : n === 2 ? 'تغييران' : n <= 10 ? `${n} تغييرات` : `${n} تغييراً`) : `${n} change${n === 1 ? '' : 's'}`);
/** استبدال {key} في نص القالب */
export function fill(tpl: string, vars: Record<string, string | number>): string { return tpl.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? '')); }
